#include <linux/key.h>
#include <linux/errno.h>
#include <linux/uaccess.h>
#include <linux/mutex.h>

long read_key_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key;
    long ret = 0;
    void *payload;
    size_t datalen;

    key = key_lookup(keyid);
    if (IS_ERR(key))
        return PTR_ERR(key);

    if (!key_perm_check(key, KEY_NEED_READ)) {
        ret = -EACCES;
        goto out;
    }

    payload = key->payload.data;
    datalen = key->datalen;

    if (buflen < datalen) {
        ret = -ERANGE;
        goto out;
    }

    mutex_lock(&key->sem);
    if (copy_to_user(buffer, payload, datalen)) {
        ret = -EFAULT;
    } else {
        ret = datalen;
    }
    mutex_unlock(&key->sem);

out:
    key_put(key);
    return ret;
}
